// clampedPercentage: given a count of covered items out of total,
// return the coverage as a percentage in [0.0, 100.0].
// Return 0.0 if total <= 0.
double clampedPercentage(int covered, int total)
{
    if (total <= 0)
        return 0.0;

    return (static_cast<double>(covered) / total) * 100.0;
}
